rows = {k: v.split('|') for k, v in rows.items()}
source = json.loads(Path('lib/l10n/app_en.arb').read_text(encoding='utf8'))
existing = {v.replace("''", "'"): k for k, v in source.items() if not k.startswith('@') and isinstance(v, str)}
mapping = {text: existing.get(text, 'capture' + ''.join(re.findall(r'[A-Za-z0-9]+', text.title()))) for text in rows['en']}
rows['pt'] = rows['pt_BR']; rows['zh'] = rows['zh_Hans']
for locale, labels in rows.items():
    assert len(labels) == len(rows['en']), (locale, len(labels))
    path = Path('lib/l10n') / f'app_{locale}.arb'; text = path.read_text(encoding='utf8'); data = json.loads(text); additions = {}
    for original, label in zip(rows['en'], labels):
        key = mapping[original]
        if key in data: continue
        additions[key] = label
        if locale == 'en': additions['@' + key] = {'description': 'Recording setup or native capture control: ' + original + '.'}
    if additions:
        path.write_text(text.rstrip()[:-1].rstrip() + ',' + json.dumps(additions, ensure_ascii=False, indent=2)[1:] + '\n', encoding='utf8')
catalog = Path('lib/l10n/message_catalog.dart'); text = catalog.read_text(encoding='utf8')
addition = ''.join(f'  {json.dumps(label)} => l10n.{key},\n' for label, key in mapping.items() if json.dumps(label) + ' =>' not in text)
catalog.write_text(text.replace('  _ => source,', addition + '  _ => source,'), encoding='utf8')
Path('docs/reports/TASK10_20261113/p1_label_mapping.json').write_text(json.dumps(mapping, indent=2), encoding='utf8')
